use std::sync::{Arc, Weak};

struct Registry { sessions: Vec<Weak<Session>> }   // must not keep sessions alive

let session = Arc::new(Session::open(addr)?);         // shared owner (thread-safe)
registry.sessions.push(Arc::downgrade(&session));     // non-owning edge
if let Some(s) = registry.sessions[0].upgrade() {     // None once the last Arc drops
    s.round_trip();
}                                                     // Drop runs at the last owner
